  const optControls=document.createElement('div');optControls.id='optControls';optControls.innerHTML='<label>Outlet configuration for design search</label><select id="optConfig"><option value="weir">Weir only</option><option value="orifice">Orifice only</option><option value="riser">Vertical riser only</option><option value="weirorifice">Weir + orifice</option><option value="weirriser">Weir + riser</option><option value="orificeriser">Orifice + riser</option><option value="all">Weir + orifice + riser</option></select><label>Search mode</label><select id="optMode"><option value="quick">Standard search: up to two outlet dimensions</option><option value="full">Advanced full search: all three outlet dimensions</option></select><label>Design objective</label><select id="optObjective"><option value="storage">Minimum required detention volume Smax</option><option value="area">Minimum plan area A</option></select><label class="checkbox"><input id="optB" type="checkbox" checked>Vary weir width b</label><div class="twocol"><div><label>Minimum b (m)</label><input id="optBmin" type="number" step="0.01" value="0.05"></div><div><label>Maximum b (m)</label><input id="optBmax" type="number" step="0.01" value="1.00"></div></div><label class="checkbox"><input id="optAo" type="checkbox">Vary orifice area Ao</label><div class="twocol"><div><label>Minimum Ao (m2)</label><input id="optAomin" type="number" step="0.001" value="0.005"></div><div><label>Maximum Ao (m2)</label><input id="optAomax" type="number" step="0.001" value="0.050"></div></div><label class="checkbox"><input id="optD" type="checkbox">Vary riser diameter D</label><div class="twocol"><div><label>Minimum D (m)</label><input id="optDmin" type="number" step="0.01" value="0.15"></div><div><label>Maximum D (m)</label><input id="optDmax" type="number" step="0.01" value="0.60"></div></div><div class="meta">Every candidate is routed with the same state equation, constraints and time step. Other geometry and coefficients remain fixed.</div>';
