  const optResult=document.createElement('div');optResult.className='chart hide';optResult.id='optResultBox';optResult.innerHTML='<h3>Recommended design dimensions</h3><div class="meta">The dimensions below are routing results for the selected configuration. “Fixed” means the value was retained from the Outlet module; “searched” means it was selected from the declared range.</div><div id="sizegraphic" aria-label="Optimized outlet dimensions"></div><div class="meta">Blue marker: selected dimension; blue line: declared search range. A fixed dimension is shown as a single marker.</div>';
