  function syncDesignControls(changed){const conf=$('optConfig').value,advanced=$('optMode').value==='full',active={optB:conf.includes('weir')||conf==='all',optAo:conf.includes('orifice')||conf==='all',optD:conf.includes('riser')||conf==='all'},ids=['optB','optAo','optD'];ids.forEach(id=>{const check=$(id),enabled=active[id],range=check.closest('label').nextElementSibling;check.disabled=!enabled;if(!enabled)check.checked=false;check.closest('label').style.opacity=enabled?'1':'.45';range.querySelectorAll('input').forEach(x=>x.disabled=!enabled);range.style.opacity=enabled?'1':'.45'});let selected=ids.filter(id=>$(id).checked),limit=advanced?3:2;if(selected.length>limit){const drop=changed&&$(changed).checked?changed:selected.at(-1);$(drop).checked=false;selected=ids.filter(id=>$(id).checked);$('optNotice').textContent='Standard search permits two variable dimensions; switch to Advanced full search to vary all three.';}else $('optNotice').textContent=advanced?'Advanced full search: up to three outlet dimensions; 3,500 candidates when all three are active.':'Standard search: up to two outlet dimensions; other active dimensions remain fixed.';$('optCurrent').textContent='Current Outlet-module dimensions (fixed unless selected for search): b = '+num('bw').toFixed(2)+' m; Ao = '+num('ao').toFixed(3)+' m²; D = '+num('riserD').toFixed(2)+' m.';}
  function declaredConfiguration(){const a=[];if($('weirOn').checked)a.push('weir');if($('oriOn').checked)a.push('orifice');if($('riserOn').checked)a.push('riser');return a.length===3?'all':a.join('');}
  function syncOptimizerFromDeclared(){const conf=declaredConfiguration();if(conf)$('optConfig').value=conf;if(conf==='all'){$('optMode').value='full';['optB','optAo','optD'].forEach(id=>$(id).checked=true);}syncDesignControls();}
  function applyOptimizerConfiguration(){const conf=$('optConfig').value;$('weirOn').checked=conf.includes('weir')||conf==='all';$('oriOn').checked=conf.includes('orifice')||conf==='all';$('riserOn').checked=conf.includes('riser')||conf==='all';if(conf==='all'){$('optMode').value='full';['optB','optAo','optD'].forEach(id=>$(id).checked=true);}$('riserBox').classList.toggle('hide',!$('riserOn').checked);renderPhysical();}
